/* R1326 — Franklin business profile-to-membership journey refinement */
(()=>{'use strict';
const RELEASE='FR-NAV1.30.26-HF3.13.8';
const path=(location.pathname.replace(/\/+$/,'/')||'/');
const es=path==='/es/'||path.startsWith('/es/');
const t=(en,sp)=>es?sp:en;
const addStyle=()=>{
  if(document.getElementById('r1326-business-style'))return;
  const s=document.createElement('style');s.id='r1326-business-style';s.textContent=`
  .r1326-business-trust{margin-top:14px;max-width:760px}.r1326-choice-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px;margin-top:22px}.r1326-choice-card{background:#fff;border:1px solid rgba(3,69,75,.15);border-radius:18px;padding:22px;box-shadow:0 8px 24px rgba(3,69,75,.05)}.r1326-choice-card h3{margin-top:0}.r1326-choice-card ul{padding-left:20px}.r1326-choice-card li+li{margin-top:7px}.r1326-choice-card.member{border-color:rgba(197,148,58,.55)}.r1326-flow{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin-top:18px}.r1326-flow span{display:block;padding:14px;border:1px solid rgba(3,69,75,.15);border-radius:14px;background:#fff}.r1326-flow strong{display:block;color:#03454b;margin-bottom:3px}.r1326-no-pay{margin-top:14px;padding:14px 16px;border-left:4px solid #03454b;background:rgba(3,69,75,.06);border-radius:10px}.r1326-member-actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:16px}.r1326-home-mini{display:grid;gap:5px}.r1326-home-mini strong{font-size:1.05rem}@media(max-width:760px){.r1326-choice-grid,.r1326-flow{grid-template-columns:1fr}.r1326-choice-card{padding:18px}}
  `;document.head.append(s);
};
const setRelease=()=>{const m=document.querySelector('meta[name="franklin-release"]');if(m)m.content=RELEASE;document.documentElement.dataset.franklinBusinessJourney='R1326'};
const enhanceHome=()=>{
  if(path!=='/'&&path!=='/es/')return;
  const section=document.querySelector('.r24-business-section');if(!section)return;
  const copy=section.querySelector('.r22-split>div:first-child');if(!copy)return;
  const e=copy.querySelector('.eyebrow'),h=copy.querySelector('h2'),p=copy.querySelector('p'),actions=copy.querySelector('.actions');
  if(e)e.textContent=t('For Franklin businesses, professionals & organizations','Para negocios, profesionales y organizaciones de Franklin');
  if(h)h.textContent=t('Find your Franklin profile. Make sure it represents you.','Encuentre su perfil de Franklin. Asegúrese de que lo represente bien.');
  if(p)p.textContent=t('Start with the public profile people can already see. Review it, request factual corrections free, then preview the richer Community Member version if you want more.','Empiece con el perfil público que las personas ya pueden ver. Revíselo, solicite correcciones factuales gratis y luego vea la versión más completa para Miembros de la Comunidad si desea más.');
  if(actions)actions.innerHTML=t('<a class="button primary" href="/claim-profile/">Find or manage my profile</a><a class="button" href="/membership-start/">See Community Membership — $35/year</a>','<a class="button primary" href="/claim-profile/">Buscar o administrar mi perfil</a><a class="button" href="/membership-start/">Ver Membresía Comunitaria — $35/año</a>');
  let trust=copy.querySelector('.r1326-business-trust');if(!trust){trust=document.createElement('p');trust.className='fine-print r1326-business-trust';copy.append(trust)}
  trust.textContent=t('Basic public profiles, factual corrections and removal requests stay free. Membership is optional and does not buy ranking, endorsement or guaranteed leads.','Los perfiles públicos básicos, las correcciones factuales y las solicitudes de eliminación siguen siendo gratis. La membresía es opcional y no compra clasificación, respaldo ni clientes potenciales garantizados.');
  const mini=section.querySelector('.r22-member-preview-mini');if(mini){mini.classList.add('r1326-home-mini');const strong=mini.querySelector('strong'),span=mini.querySelector('span');if(strong)strong.textContent=t('$35/year Community Membership','Membresía Comunitaria — $35/año');if(span)span.textContent=t('Reviewed About · services · hours · photos · verified website, booking & social links','Información revisada · servicios · horarios · fotos · sitio web, reservas y enlaces sociales verificados')}
};
const enhanceBusiness=()=>{
  if(path!=='/business-dashboard/'&&path!=='/es/negocios/')return;
  const hero=document.querySelector('.r29-hero');if(!hero)return;
  const h=hero.querySelector('h1'),lead=hero.querySelector('.r29-lead'),status=hero.querySelector('[data-business-status]'),actions=hero.querySelector('.actions');
  if(h)h.textContent=t('Find your Franklin profile, then improve it.','Encuentre su perfil de Franklin y luego mejórelo.');
  if(lead)lead.textContent=t('Your basic public profile is free. Find it first, review what people can see, and request factual corrections or removal at no charge. Then decide whether $35/year Community Membership is useful for you.','Su perfil público básico es gratis. Encuéntrelo primero, revise lo que las personas pueden ver y solicite correcciones factuales o eliminación sin costo. Luego decida si la Membresía Comunitaria de $35 al año le resulta útil.');
  if(status)status.textContent=t('Start with the public profile that already represents your business, practice or organization.','Empiece con el perfil público que ya representa a su negocio, práctica u organización.');
  if(actions){const primary=actions.querySelector('[data-business-primary]')||actions.querySelector('.primary');if(primary){primary.href='/claim-profile/';primary.textContent=t('Find or manage my profile','Buscar o administrar mi perfil')}const secondary=actions.querySelector('[data-business-secondary]');if(secondary){secondary.href='/member-profile-preview/';secondary.textContent=t('Preview the richer member profile','Ver el perfil de miembro más completo')}if(!actions.querySelector('.r1326-membership-link')){const a=document.createElement('a');a.className='button r1326-membership-link';a.href='/membership-start/';a.textContent=t('See membership — $35/year','Ver membresía — $35/año');actions.append(a)}}
  const pathSection=document.querySelector('.hf310-path-section');const flow=pathSection?.querySelector('.hf310-path');if(flow){flow.classList.add('r1326-flow');flow.innerHTML=t('<span><strong>1 · Find profile</strong>See the public page people already find.</span><span><strong>2 · Review facts</strong>Request factual corrections or removal free.</span><span><strong>3 · Preview member profile</strong>See the richer reviewed version before paying.</span><span><strong>4 · Join if useful</strong>$35/year, optional.</span>','<span><strong>1 · Buscar perfil</strong>Vea la página pública que las personas ya encuentran.</span><span><strong>2 · Revisar datos</strong>Solicite correcciones factuales o eliminación gratis.</span><span><strong>3 · Ver perfil de miembro</strong>Vea la versión revisada más completa antes de pagar.</span><span><strong>4 · Unirse si le sirve</strong>$35/año, opcional.</span>')}
  const note=pathSection?.querySelector('.hf310-path-note');if(note)note.textContent=t('You do not need to become a member to fix public facts. Membership is for a richer reviewed profile and additional business tools.','No necesita hacerse miembro para corregir datos públicos. La membresía ofrece un perfil revisado más completo y herramientas adicionales para negocios.');
  if(pathSection&&!document.querySelector('.r1326-business-choices')){const s=document.createElement('section');s.className='section r1326-business-choices';s.innerHTML=t('<div class="wrap"><div class="eyebrow">Free profile vs. Community Membership</div><h2>Choose based on what you need—not to fix accuracy.</h2><div class="r1326-choice-grid"><article class="r1326-choice-card"><h3>Your public profile stays free</h3><ul><li>Public profile based on available source-backed information</li><li>Free factual corrections and removal requests</li><li>Ordinary Directory placement is not improved by paying</li></ul><a class="button primary" href="/claim-profile/">Review my public profile</a></article><article class="r1326-choice-card member"><h3>Community Membership — $35/year</h3><ul><li>Richer reviewed About, services, hours and photos</li><li>Verified website, phone, email, booking, quote, order, menu and social links where applicable</li><li>No Similar local profiles section on your active member profile</li><li>Additional local business tools and member support</li></ul><a class="button primary" href="/membership-start/">See exactly what membership adds</a></article></div><p class="fine-print r1326-no-pay"><strong>No paid ranking or endorsement.</strong> Membership does not guarantee leads, customers, availability or placement. Public-source facts and member-provided information remain distinct and are reviewed before publication.</p></div>','<div class="wrap"><div class="eyebrow">Perfil gratis vs. Membresía Comunitaria</div><h2>Elija según lo que necesite, no para corregir la precisión.</h2><div class="r1326-choice-grid"><article class="r1326-choice-card"><h3>Su perfil público sigue siendo gratis</h3><ul><li>Perfil público basado en información disponible respaldada por fuentes</li><li>Correcciones factuales y solicitudes de eliminación gratis</li><li>Pagar no mejora la ubicación ordinaria en el Directorio</li></ul><a class="button primary" href="/claim-profile/">Revisar mi perfil público</a></article><article class="r1326-choice-card member"><h3>Membresía Comunitaria — $35/año</h3><ul><li>Información, servicios, horarios y fotos revisados y más completos</li><li>Sitio web, teléfono, correo, reservas, cotizaciones, pedidos, menú y enlaces sociales verificados cuando corresponda</li><li>Sin sección de perfiles locales similares en su perfil de miembro activo</li><li>Herramientas adicionales para negocios y apoyo para miembros</li></ul><a class="button primary" href="/membership-start/">Ver exactamente lo que añade la membresía</a></article></div><p class="fine-print r1326-no-pay"><strong>Sin clasificación pagada ni respaldo.</strong> La membresía no garantiza clientes potenciales, clientes, disponibilidad ni ubicación. Los datos de fuentes públicas y la información proporcionada por miembros se mantienen separados y se revisan antes de publicarse.</p></div>');pathSection.insertAdjacentElement('afterend',s)}
  const membership=document.querySelector('.hf310-dashboard-membership');if(membership){const card=membership.querySelector('.hf310-dashboard-card');const title=card?.querySelector('h2'),list=card?.querySelector('ul'),cta=card?.querySelector('[data-business-membership-cta]');if(title)title.textContent=t('Community Membership — $35/year','Membresía Comunitaria — $35/año');if(list)list.innerHTML=t('<li>Richer reviewed business profile</li><li>Services, hours, photos and verified customer-action links</li><li>Verified official website and social links where applicable</li><li>No Similar local profiles on your active member profile</li>','<li>Perfil de negocio revisado y más completo</li><li>Servicios, horarios, fotos y enlaces de acción verificados</li><li>Sitio web oficial y enlaces sociales verificados cuando corresponda</li><li>Sin perfiles locales similares en su perfil de miembro activo</li>');if(cta){cta.href='/membership-start/';cta.textContent=t('See Community Membership — $35/year','Ver Membresía Comunitaria — $35/año')}}
};
const enhanceMembership=()=>{
  if(path!=='/membership-start/'&&path!=='/business-membership/')return;
  const hero=document.querySelector('main section:first-child');if(!hero)return;
  const h=hero.querySelector('h1'),p=hero.querySelector('.r29-lead')||hero.querySelector('p'),actions=hero.querySelector('.actions');
  if(h)h.textContent='See what Community Membership adds to your Franklin profile.';
  if(p)p.innerHTML='Community Membership is optional at <strong>$35/year</strong>. Start with your existing public profile, which remains free to review, correct or remove. Join only if the richer reviewed profile and member tools are useful to you.';
  if(actions)actions.innerHTML='<a class="button primary" href="/claim-profile/">Find or manage my profile first</a><a class="button" href="/member-profile-preview/">Preview my member profile</a><a class="button" href="/membership-enroll/">Start membership setup</a>';
  const benefits=document.querySelector('.hf310-membership-benefits')||document.querySelectorAll('main .section')[1];
  if(benefits&&!document.querySelector('.r1326-membership-start-first')){const s=document.createElement('section');s.className='section tint r1326-membership-start-first';s.innerHTML='<div class="wrap"><div class="eyebrow">Start with what people already see</div><h2>Review first. Upgrade second.</h2><div class="r1326-flow"><span><strong>1 · Find your profile</strong>Open the public profile tied to your business or organization.</span><span><strong>2 · Check the facts</strong>Corrections and removal requests are free.</span><span><strong>3 · Preview the richer version</strong>See the reviewed member layout and eligible links before paying.</span><span><strong>4 · Join only if it fits</strong>$35/year, billed annually until canceled.</span></div><p class="r1326-no-pay"><strong>Membership does not buy accuracy, ranking or endorsement.</strong> It adds profile depth and member tools. It does not guarantee leads or customers.</p></div>';hero.insertAdjacentElement('afterend',s)}
  const decision=document.querySelector('.hf310-decision-card');if(decision){const cta=decision.querySelector('[data-hf310-membership-cta]')||decision.querySelector('.button.primary');if(cta){cta.href='/membership-enroll/';cta.textContent='Start membership setup — $35/year'}if(!decision.querySelector('.r1326-member-actions')){const div=document.createElement('div');div.className='r1326-member-actions';div.innerHTML='<a class="button" href="/member-profile-preview/">Preview the member profile first</a><a class="button" href="/claim-profile/">Review my free public profile</a>';decision.append(div)}}
};
const enhanceEnroll=()=>{if(path!=='/membership-enroll/')return;const hero=document.querySelector('.r29-hero .wrap');if(!hero||hero.querySelector('.r1326-no-pay'))return;const p=document.createElement('p');p.className='fine-print r1326-no-pay';p.innerHTML='<strong>Before you join:</strong> your basic public profile, factual corrections and removal requests remain free. Membership is optional and does not buy ranking, endorsement or guaranteed leads.';hero.append(p)};
const run=()=>{addStyle();setRelease();enhanceHome();enhanceBusiness();enhanceMembership();enhanceEnroll()};
document.readyState==='loading'?document.addEventListener('DOMContentLoaded',run,{once:true}):run();
})();
